import type { Story } from "./stories";

export const stories2300: Record<number, Story> = {
	2300: {
		index: 2300,
		text: `<p>You attempt to deceive the 'efreet into believing you are not the one he seeks.</p>
<p><b>No Skill:</b> It doesn't work and the 'efreet wreaks his vengeance. [S1/<em>Crippled</em>/Have another player move you to any city]</p>
<p><b>Acting and Disguise:</b> Though you don different clothes and put on a different manner, the 'efreet sees right through your performance. Still, it buys you a few extra steps, and when the lightning strikes, you are only hurt rather than killed. [S1/<em>Wounded</em>]</p>
<p><b>Protective Talisman:</b> The 'efreet swells in anger. "Are you trying to deceive me?" You smile and reply, "I don't have to," as you show him the magical artifact you have in your possession. The 'efreet's demeanor changes dramatically as he cowers and bows his head. "What is it you wish of me, master?" [D1/S1/Choice of <b>Seal Ring</b> or <b>Magic Lamp</b>]</p>`,
	},
	2301: {
		index: 2301,
		text: `<p>In the bustling bazaar you weave through people and tents until you believe you have lost your pursuer.</p>
<p><b>No Skill:</b> You are proven wrong. Very wrong. [S1/<em>Crippled</em>]</p>
<p><b>Acting and Disguise:</b> Even though you switched clothes while running through the bazaar, you are proven wrong: the 'efreet finds you! And he is not happy for the chase. He beats you, then strips you of your clothes and possessions. [S1/W-6 (Min: Beggar)/<em>Crippled</em>]</p>
<p><b>Protective Talisman:</b> You stop in an alley to catch your breath, but the 'efreet is there, waiting for you. "Vengeance is mine!" he shouts. You fumble in your robes and pull out a magical artifact. The 'efreet snarls, then disappears in a cloud of foul-smelling smoke. [D1/S1]</p>`,
	},
	2302: {
		index: 2302,
		text: `<p>You have decided to take a voyage and one evening you see the other wailing while tossing something over the side of the boat. You are concerned that the other is tossing items of the passenger's overboard. You attack!</p>
<p><b>No Skill, Weapon Use</b> [mandatory]: The other cries out and says that he is tossing the remains of his crushed sculpture collection. A rival came and smashed it in his absence. Touched by the tale you cease your attack and offer the other some money to start his collection again. [D1/W-2 (Min: Poor)]</p>
<p><b>Seamanship:</b> The other cries out and says that he is tossing the remains of his crushed sculpture collection. A rival came and smashed it in his absence. Looking at the bits of sculpture you recognize some of it from your journeys. You tell the other of a spot where he can fish some up from where a ship sank not too long ago. The other thanks you profusely. [D1/<em>Respected</em>]</p>`,
	},
	2303: {
		index: 2303,
		text: `<p>You have decided to take a voyage and see the other drifting in a small boat. The other seems to be wailing while tossing something over the side of the boat. You are suspicious of the other and think there must be foul play involved.</p>
<p><b>No Skill:</b> You try to convince the captain of your vessel to aid you in attacking the other's small craft. The captain offers you a dinghy of your own to go after the other. You take him up on the offer but you are unable to navigate the dinghy to the other's boat. You drift for a few days before another ship picks you up. [S1/Seamanship/<em>Envious</em>/<em>Wounded</em>/Have another player move you to any coastal space]</p>
<p><b>Seamanship</b> [mandatory]: You convince the captain to turn his vessel upon the other. The other turns out to have stolen from a friend and has decided that he cannot profit thusly. He further cannot tell his friend, and is therefore tossing the treasures into the waters. You are able to save some of the items and bring the other to justice. There is a fine, yet tearful reward. [D1/S1/W+2 (Max: Princely)/<b>Treasure</b>]</p>`,
	},
	2304: {
		index: 2304,
		text: `<p>One evening, on a voyage, you see the other, a known scoundrel, threatening a fellow passenger. You spring into action, attacking the other. Alas, too soon you discover that the other was acting righteously—his "victim" was a far worse villain.</p>
<p><b>No Skill, Weapon Use</b> [mandatory]: Your quick and decisive blows slew the other before the truth could come out. You are thrown into the brig for the remainder of the voyage. [D1/Quick Thinking/Have another player move you to any coastal space]</p>
<p><b>Seamanship:</b> Despite the rocking of the ship, your blows were carefully aimed and delivered, allowing you to fell the other without permanent harm. As you discover the truth, you work with the other to apprehend the thief. You offer to pay for the other's treatments. [D1/S1/W-1 (Min: Poor)/Quick Thinking]</p>`,
	},
	2305: {
		index: 2305,
		text: `<p>You choose to take a voyage and meet the other aboard. You soon decide that the other is an infidel and must be dealt with. Unfortunately the other has many followers aboard and you are easily subdued and tossed over.</p>
<p><b>No Skill:</b> You wash up on shore, unsure of who you are. [D1/W-2 (Min: Penniless)/<em>Insane</em>/<em>Wounded</em>/Have another player move you to any coastal space]</p>
<p><b>Seamanship:</b> You are deft enough at swimming that you can reach the dinghy dragged by the ship. You cut the tether and row to the shore. [S1/Luck/Have another player move you to any coastal space]</p>`,
	},
	2306: {
		index: 2306,
		text: `<p>Listening to the other you find him quite wise...until you realize that he is planning a grand swindle for which you will be blamed! You take no time for questions—you attack!</p>
<p><b>No Skill:</b> The other is surprisingly agile and tosses you into a nearby river. You cannot swim and soon you feel that you are going to drown. Before you lose consciousness, hands begin to grab you and draw you down to the bottom of the sea. [D1/Seamanship/Weapon Use/Move to the Undersea Kingdom and have an immediate encounter]</p>
<p><b>Weapon Use:</b> The other is surprising agile and almost bests you. But your experience allows you to get the upper hand at the last moment and toss the other into the nearby river. You declare what you have done to all who gather to watch the struggle, and at your words they suggest that you keep the other's possessions. [S1/<b>Treasure</b>]</p>`,
	},
	2307: {
		index: 2307,
		text: `<p>The other speaks of interesting things from far-off places. You note before it's too late that you and the others listening are being lulled by a spell. You attack!</p>
<p><b>No Skill:</b> You beat the other soundly and the listeners hail your insight. [D1/Seduction/<em>Respected</em>]</p>
<p><b>Weapon Use:</b> The other grabs a basket and swings it at you. You experience comes into play as you avoid the blow and take the makeshift weapon from the other. With a single strike you render the other harmless. Now you must deal with the other's followers.</p>
<p><b>No Skill:</b> You are beaten and thrown into an alley. Apparently they continued to be under the other's spell. [D1/<em>Envious</em>/<em>Scorned</em>]</p>
<p><b>Appearance:</b> You stun the others with your visage long enough to explain that they are under a spell. Enough of the others shake it off to save you from a horrible fate. [D2/Seduction]</p>`,
	},
	2308: {
		index: 2308,
		text: `<p>Something strikes you that the other seems like a good target for ransom. You begin to plot a kidnapping.</p>
<p><b>No Skill:</b> Disguised as a holy man, you set a trap for the other. Your disguise helps you to gain the other's trust enough for you to get the drop on him. Unfortunately, you were wrong about the other's worth. You discover that his crafter nature tricked you. The joke was on both of you in the end. You release the other in the woods and disappear yourself, never to return to this area without a new disguise. [S1/Acting and Disguise]</p>
<p><b>Wilderness Lore:</b> You disguise yourself as a being of the woods and lure the other into your trust...That's what you think, anyway. You find that you are the one who is captured, only to be let loose again when the other discovers that you're not really a magical being of the woods. [D1/Appearance/Acting and Disguise]</p>
<p><b>Seamanship:</b> You discover that the other is bound for a sea journey and you decide that this is when you shall strike. You take the other by surprise before he boards and you assume his identity for the voyage, abandoning your plan to kidnap him. The trick is on you as the other is wanted and you are the one who is jailed. [D2/Stealth and Stealing/<em>Imprisoned</em>]</p>`,
	},
	2309: {
		index: 2309,
		text: `<p>You decide to take a voyage and encounter the other on the ship. He seems a good candidate for a kidnapping.</p>
<p><b>No Skill:</b> Try as you might, you cannot trick the other into showing a weakness. Your attempts are unsuccessful. [Acting and Disguise/Stealth and Stealing]</p>
<p><b>Seamanship:</b> You know that the other will have to attend to a certain area of the ship at some point—a secluded area. You wait there for the other near the end of the voyage and waylay him. The other is not missed as you cart him off the vessel in a trunk. The ransom is small, but worth your efforts. [S1/W+1 (Max: Rich)]</p>`,
	},
	2310: {
		index: 2310,
		text: `<p>You decide to take a voyage where you meet the other. The other seams a good candidate for a kidnapping.</p>
<p><b>No Skill:</b> You try to lure the other into a secluded area of the ship. Your attempts fail. [D1/Seduction]</p>
<p><b>Seamanship:</b> You lull the other into a false sense of security with tales of sailing and boat craft. You do not notice that the whole time, the other has slowly been plying you with drink after drink. You awaken after the ship has docked to find your purse gone. [S1/W-2 (Min: Penniless)/Seduction]</p>`,
	},
	2311: {
		index: 2311,
		text: `<p>Hired to retrieve a man from a gang of bandits, your new employer told you where and when to best find your target. So that very night you creep up to the gang's campfire, where you see a person sitting: the person who hired you!</p>
<p><b>No Skill:</b> You freeze in confusion as the man turns to you and smiles. You then find a scimitar across your throat: the trap they set has closed upon you. Fortunately, they are so amused by their own skill that they let you off easily. [D-1/S-1/W-2 (Min: Poor)]</p>
<p><b>Stealth and Stealing:</b> It would have been a perfect trap—if you hadn't recognized the person hiring you as himself a renowned thief. Your "target" smiles, expecting the trap to close shut right about now, but the thug who he expected to come up behind you was waylaid by a pit you dug out earlier. You casually saunter forward toward the thief, his smile vanishing. [D1/S2/W+2 (Max: Respectable)/Stealth and Stealing]</p>`,
	},
	2312: {
		index: 2312,
		text: `<p>Your pockets were picked by an expert and you have lost not a few bits of gold. Fortunately, you know of a thief who owes you a favor and could help you recover your stolen money. Unfortunately, your acquaintance is imprisoned and will be publicly executed the next day.</p>
<p><b>No Skill:</b> He is too heavily guarded for you to reach him by force, nor have you coin enough to bribe the guards. [W-1 (Min: Poor)]</p>
<p><b>Stealth and Stealing, Beguiling:</b> Through sneaking in the dark corners and fast talking in the open light, you are able to meet with the thief in his cell and tell your tale. He agrees to help if you save him from his fate. At the next dawn, a distraction you engineered allows you to ride by on a swift horse and lift the thief up into your saddle, his guards still confused and clueless. He repays you as promised, helping you to recover your stolen property. [D2/S1]</p>`,
	},
	2313: {
		index: 2313,
		text: `<p>You are asked to rescue a man who is caught up in some intrigue. However, soon after, you see that same man helping bandits steal from a merchant. You do not care to help a thief and therefore abandon the mission. [D1/S1]</p>`,
	},
	2314: {
		index: 2314,
		text: `<p>The slave is purchasing food for his master's dinner, going about from merchant to merchant, checking the quality of the food and haggling prices. He pays you not the slightest attention. [S1]</p>`,
	},
	2315: {
		index: 2315,
		text: `<p>You realize it is folly to importune a slave belonging to another in the middle of his work. [D1]</p>`,
	},
	2316: {
		index: 2316,
		text: `<p>The slave is running from merchant to merchant, trying to complete the tasks set to him by his master. He has no time to discuss business with you—if he is late, he will suffer a rude beating. If you truly want his services, you will need to purchase him from his master.</p>
<p><em>Do you wish to purchase him, and do you have a Wealth level of at least Rich?</em></p>
<p><em>If you do not want to purchase this slave or have Wealth less than Rich:</em> You thank him and go on your way. [D1]</p>
<p><em>If you do want to purchase this slave:</em> You go to his master's home and ask to purchase the slave. The man asks for a lot of money, far more than the slave is worth.</p>
<p><b>No Skill:</b> You realize it is not worth the time or effort to pursue and you go about your way. [D1]</p>
<p><b>Beguiling:</b> You are able to haggle with the owner and bring down the price to a fair amount. The slave proves incredibly able and even teaches you a few things. [D1/S1/W-1 (Min: Poor)/Bargaining and Evaluation]</p>`,
	},
	2317: {
		index: 2317,
		text: `<p>Seeing as the 'efreet is an intelligent being, perhaps reasoning will resolve this situation.</p>
<p><b>No Skill:</b> The 'efreet ignores your words as if you were a worm and proceeds to exact his vengeance. [S1/<em>Crippled</em>]</p>
<p><b>Beguiling, Protective Talisman:</b> Your words penetrate the haze of hatred surrounding the 'efreet. He listens intently and finally he says, "I see that your intentions were not of a malicious nature and therefore I forgive you." The 'efreet vanishes in a cloud of smoke, leaving you unharmed. [D1/S1]</p>`,
	},
	2318: {
		index: 2318,
		text: `<p>Believing that running away will not help you, you attempt another tactic—that of trying to talk with your enemy. The 'efreet ignores your words as if you were a worm and proceeds to exact his vengeance. [S1/<em>Crippled</em>]</p>`,
	},
	2319: {
		index: 2319,
		text: `<p>You think it can't hurt to talk to this imposing enemy.</p>
<p><b>No Skill:</b> "A mortal who dares to speak to one of the Dusky race must be a complete stranger to fear. I respect that and leave you be." [D1/S1]</p>
<p><b>Storytelling:</b> You begin with a short, amusing tale and the 'efreet laughs. Encouraged by this reaction, you begin to weave a string of tales, some light-hearted and some quite dramatic: they are the stories of your own adventures. Time marches on and exhaustion thickens your tongue so that you must stop. Apprehensively, you look at the 'efreet, waiting for some reaction—and the 'efreet responds with delightful clapping. "Mortal, I have not been entertained so in a long while. Please accept this gift." He vanishes, leaving a wondrous object in front of you. [D1/S1/<b>Treasure</b>]</p>`,
	},
	2320: {
		index: 2320,
		text: `<p>"And what paltry sum can you offer to make it worth my while?"</p>
<p><b>No Skill:</b> You realize no matter what sum you offer the other will still refuse. [S1]</p>
<p><b>Beguiling:</b> You tell him that while you can't offer anything up front for his services, you will give up the first instance of wealth gained. Your words are convincing enough for the other to agree to your deal. [D1/Magic/The next time you gain Wealth from an award, it is immediately given away as per your deal]</p>`,
	},
	2321: {
		index: 2321,
		text: `<p>The other is known to possess great power.</p>
<p><b>No Skill:</b> "Before I agree to help you, you must do one thing for me. Go to the Sultan's palace and tell him you have a message from me." The next day you go to the Sultan's palace and are given an immediate audience upon mentioning the other by name. The Sultan claps his hands in delight and guards grab your arms. "We are finally able to mete out justice for the transgressions of your friend." No matter what you say to the contrary, you are beaten in front of a large audience. [S1/<em>Wounded</em>/<em>Scorned</em>]</p>
<p><b>Brass Trumpet</b> [mandatory]: The trumpet lets out a warning of impending deceit. The other is so startled by the noise, he runs, dropping a purse full of gold. [D1/W+1 (Max: Rich)]</p>`,
	},
	2322: {
		index: 2322,
		text: `<p>The other is known to possess knowledge of the deepest secrets.</p>
<p><b>No Skill:</b> Unfortunately, the other also knows that you cannot afford his services.</p>
<p><b>Acting and Disguise, Courtly Graces:</b> You put on noble airs and begin to state your business.</p>
<p><em>If your Wealth is Respectable or lower:</em> After a short time with you, the other figures out your true state of being and departs from your company. [D1]</p>
<p><em>If your Wealth is Rich or greater:</em> Your performance excites his greed and he eagerly helps fulfill your quest. [D2/S1/W-1 (Min: Respectable)/<b>Treasure</b>]</p>`,
	},
	2323: {
		index: 2323,
		text: `<p>When the robed other passes by, you bump into him, your hand darting into his robes. As you try to remove your hand, you realize it is stuck in a thick liquid, like watered honey. "Aha! You've been snared by my ingenious anti-pickpocket device. Now you shall pay for your transgression." The other tries to cast a spell, but the substance holding you causes the both of you to be entangled in an awkward position.</p>
<p><b>No Skill:</b> Passersby laugh at the spectacle of the "two-headed" fool. [<em>Scorned</em>]</p>
<p><b>Storytelling, Acting and Disguise:</b> You make the best of the situation and begin performing a dumb-show for the people passing by. Some even throw coins for your performance, which, alas, you must share with your "partner." Still, you manage to turn a small profit before you can extricate your hand and flee. [S1/W+1 (Max: Poor)/Choice of Storytelling or Acting and Disguise]</p>`,
	},
	2324: {
		index: 2324,
		text: `<p>The other is carrying a bubbling potion in a decorated pottery jar. As he comes near, he trips on his robes and falls. As you go to help him up, you espy a bulging purse at his waist.</p>
<p><b>No Skill:</b> You try to relieve the other of his belongings, but you are caught. "Fool! How dare you?" He draws himself up to call down a great curse on you, but as he raises his hands, he slips again on the liquid. You quickly make your escape before he can regain his feet. [S1/Quick Thinking]</p>
<p><b>Stealth and Stealing:</b> You deftly remove the purse as you lift the other off the ground. The other thanks you profusely and offers a reward, but as he reaches for where the purse once dwelled, you stay his hand. "No reward is necessary for aiding a fellow True Believer." [S2/W+2 (Max: Respectable)]</p>`,
	},
	2325: {
		index: 2325,
		text: `<p>The old other is struggling with a huge rock. You can't understand the reason behind their action but you see an opportunity....</p>
<p><b>No Skill:</b> The other is startled by your approach and drops the rock on your foot. You hop around hurling expletives, while the other wanders off, muttering "Ah, so that's what happens when you lift more than you can carry." [D1/<em>Wounded</em>]</p>
<p><b>Stealth and Stealing:</b> You approach silently, but still the old one is startled and drops the rock. You wince in anticipation of the impact, but it never comes: the rock is floating in the air. "You thought I was going to drop this rock on your foot, did you not? Well, only a skilled wielder of magic like myself can...." With that, the rock falls on your foot. "Whoops." The other skulks away, leaving you howling in pain. [<em>Wounded</em>]</p>`,
	},
	2326: {
		index: 2326,
		text: `<p>The other is profuse in his thanks. "Thank you for testing my new potion. It shall increase your strength tenfold!"</p>
<p><b>No Skill:</b> You eagerly accept a draught of the fabricated liquid. Immediately, you notice your muscles knot tighter, and you indeed feel much stronger. You go to look at yourself in a nearby mirror and see an ape staring back at you. "That was not supposed to happen," says the other. [S1/<em>Beast Form</em>]</p>
<p><b>Magic:</b> From your studies in the arcane arts you notice the color of the liquid appears wrong. You pretend to drink the potion and then put on a display of strength. The other is delighted at the efficacy of his potion and happily hops back to his workshop. [D1/Acting and Disguise]</p>`,
	},
	2327: {
		index: 2327,
		text: `<p>"A spell is a complicated thing," the other says. "And it's so hard to get test subjects." Before you can respond, the other chants a quick phrase in a harsh language you can't understand.</p>
<p><b>No Skill:</b> In a trice, a great djinn appears before you! The other is even more surprised than you. The djinn grabs you and whisks you away to a land beyond men. [D1/Move to the Dusky Land and have an immediate encounter]</p>
<p><b>Scholarship:</b> You recognize that the words are in an ancient form of the tongue of the Fire-Worshipping Magians. No good can possibly come from allowing the other to complete his invocation. You stop the other and rescind your offer of help. [S1]</p>
<p><b>Pursued</b> [mandatory]: Before the other even finishes his words, you are greeted by a harsh cry from behind you both. Turning, you discover your most hated enemy stands there, puzzled how he came to this place. "That wasn't supposed to happen," the other says. [D1/Have an immediate encounter with your Pursuer on the Pursuing line of Matrix H]</p>`,
	},
	2328: {
		index: 2328,
		text: `<p>A strange denizen of the sea invites you to celebrate with him the rising tide. Standing just off the shore in inches of water you face the horizon, letting water drain between your fingers. You give a prayer to the Most High for gifting you this moment of beauty. [S1/Piety]</p>`,
	},
	2329: {
		index: 2329,
		text: `<p>A merman invites you to participate in his people's tradition of celebrating the rising tide with prayer.</p>
<p><b>No Skill:</b> You don't want to insult you new friend so you join him in prayer. [D1]</p>
<p><b>Piety:</b> You do not want to insult your friend, but you tell him that your faith cannot allow you to do such a thing. However, you would be willing to teach him the prayers to the One God, and the merman accepts this teaching graciously. [D2/Piety]</p>`,
	},
	2330: {
		index: 2330,
		text: `<p>To your amazement, a merman invites you under the waters to dine with his family. At the dinner table, before you can eat, everyone holds hands and prays for the food on the table. Then you join the merfolk as they dance around the table—three times to the left, then three times to the right. You don't understand what is going on, but you have worked up such an appetite so that when the prayers are done you are eager to eat. [D1/S1]</p>`,
	},
	2331: {
		index: 2331,
		text: `<p>While the treasure is tempting, its guards are too imposing for you to try anything, so you move on. [D-1]</p>`,
	},
	2332: {
		index: 2332,
		text: `<p>As you walk by you feel the eyes of the guards upon you. [S1]</p>`,
	},
	2333: {
		index: 2333,
		text: `<p>The treasure, though small, is breathtaking, as breathtaking as the guards are fierce. You take a step closer and the guards narrow their eyes, and you turn away.</p>
<p><b>No Skill:</b> As each step carries you further from the treasure, it grows larger in your mind, in your imagination surpassing all else you have seen. For days, the idea of going back to the treasure gnaws at you, and when finally you return, it is gone. [D1/<em>Envious</em>]</p>
<p><b>Weapon Use:</b> You finger your sword absentmindedly as you walk by. The guards snort derisively at you, "Look, he's thinking to make off with the treasure." The guards laugh.</p>
<p><em>Do you walk away or do you draw your sword?</em></p>
<p><em>If you walk away:</em> You will not be forced to do what you don't want to do. [D1]</p>
<p><em>If you draw your sword:</em> Their laughter insults you and you take up their challenge. Your dazzling display of swordsmanship leaves many wounds upon the guards. However, you do not take the now-unguarded treasure, as a final rebuff to their derision. [D1/S1]</p>`,
	},
	2334: {
		index: 2334,
		text: `<p>You have come to a town where the people practice layer upon layer of ritual. Before you can enter, you are asked to do many strange things. After half a day of questions and songs and recitations, finally, you are asked to remove your clothes and be bathed in a nearby shallow pool.</p>
<p><em>You may change your mind or continue.</em></p>
<p><em>If you change your mind:</em> You've done what they have asked up until this point but you feel this last custom is ridiculous—all this just to enter a small village. Only so much will you endure before you walk away. [S1]</p>
<p><em>If you continue:</em> You have done other things they have required of you and while this last one seems unreasonable, you do not wish to insult them. You agree, but before you remove any clothing, the villagers shout, "Thank Allah!" and suddenly the village and its people are transformed into a city and people of splendor. You are told that they were under a curse and they required to have a stranger agree to following all their ridiculous customs in order to free themselves of this enchantment. They reward you handsomely for your perseverance. [D2/S1/W+2 (Max: Princely)/Enduring Hardship/<em>Blessed</em>]</p>`,
	},
	2335: {
		index: 2335,
		text: `<p>As you sail, you come across the captain looking out in the water. Suddenly, he pales at some distant sight and throws up his hands in some sort of intricate warding gesture. You think it could not hurt to copy him and note the gesture for the future. [S1]</p>`,
	},
	2336: {
		index: 2336,
		text: `<p>A dendan passes by the ship, causing a panic among the crew. The captain begins to chant and gesture strangely, and quickly the rest of the crew begins to do the selfsame thing.</p>
<p><b>No Skill:</b> You can only assume this has something to do with the dendan and the safety of the ship, so you join the chant as well. Your ship sails along unharmed. [S1]</p>
<p><b>Scholarship:</b> You begin to chant along with the others but then realize the ridiculousness of the situation. Only a shout from a human will protect them against a dendan, not this peculiar ritual. One of the crew sees your refusal to join in, and when the captain learns, he orders you bound and thrown into the cargo hold. In the very moment that your wrists are tied, the dendan attacks the ship, shattering it. [Go to paragraph 2340]</p>`,
	},
	2337: {
		index: 2337,
		text: `<p>The captain asks you to join him in his cabin. You follow him inside, whereupon immediately he admits he fears a mutiny is brewing. He wants to know if he can count on your loyalty. While he talks, your eyes scan the cabin and its treasures from past raids.</p>
<p><b>No Skill:</b> Unfortunately, you are swept up in the mutiny when it happens and the new captain does not give you an opportunity to visit his cabin. [S1]</p>
<p><b>Stealth and Stealing:</b> While the mutiny takes place, you are able to sneak into the cabin, take some choice items, then return to the deck before anyone notices you are missing. [D1/S1/W+1 (Max: Rich)]</p>
<p><b>Bargaining and Evaluation:</b> While the mutiny takes place, you are able to sneak into the cabin, and take the one item that really caught your attention earlier. [D1/S1/<b>Treasure</b>]</p>`,
	},
	2338: {
		index: 2338,
		text: `<p>The captain's paranoia seems to increase every day, and every day he sits in his cabin, most likely protecting his hoard.</p>
<p><b>No Skill:</b> In a rare moment when he is of the captain's absence from the cabin, you sneak in and grab some items. Later, the captain calls all hands on deck and declares that someone has stolen from him and produces page upon page of tightly written manifests to prove his case. He declares the ship will not enter port until the culprit is found. The crew has had enough, mutinies, and throws the captain overboard. You have gotten away cleanly but feel very sad at the loss of the captain. [D1/W+2 (Max: Rich)/<em>Grief Stricken</em>]</p>
<p><b>Luck:</b> While the captain goes on some rounds, you attempt to sneak into his cabin. However, someone is there before you! Lest you get caught, you overpower the villain from behind, just as the captain returns suddenly. He sees that you have stopped a thief and rewards you generously, as well as making you his first mate. [D2/S1/W+3 (Max: Rich)/Quick Thinking]</p>`,
	},
	2339: {
		index: 2339,
		text: `<p>The captain, a superstitious man, believes that if ever he loses the golden feather in his hair, the ship will be lost. You don't believe that, and the feather would make a nice addition to your coffers. One night, as the captain sleeps, you steal the feather, but after only a few steps out of the room, the ship begins to list wildly. Screams break out above you and your only thought now is to return the feather. You open to the door to the cabin to see the captain standing there. He plucks the feather from your hands and dons it: the ship calms immediately. "Sometimes I have to remind my crew that I am not crazy." He returns to his bunk and goes back to sleep. From that point on, you strive to be the best sailor possible. [D1/S1/Seamanship]</p>`,
	},
	2340: {
		index: 2340,
		text: `<p>Your ship has been destroyed by a dendan! You hold on to some floating jetsam as the water froths about you. You are trying to shout, but water keeps entering your mouth. Suddenly, a merman appears next to you and bids you to follow him underwater.</p>
<p><b>No Skill:</b> Your situation compels you to follow, even though you don't know how you will survive. The merman puts some strange oil on you and pushes you underwater. You're scared at first but then you realize you can move and breathe underwater as if on land. With renewed confidence, you follow the merman to his abode where you are treated like family. After a few days of generous hospitality, the merman brings you back to the dry land... along with some gifts. [D2/S2/Luck/<b>Dendan Oil</b>]</p>
<p><b>Seamanship:</b> You are grateful for the assistance, but you explain that your skills lie on the surface of the water, not underneath. You ask to be taken to dry land to await a proper rescue. [S1]</p>`,
	},
	2341: {
		index: 2341,
		text: `<p>While you are fishing, you see a merman's head break the surface. Immediately you fall to friendly conversation. After a few hours of discourse, the merman invites you to his world. You agree and are shown such wondrous sights as few surfacemen have ever seen. [Move to the Undersea Kingdom and have an immediate encounter]</p>`,
	},
	2342: {
		index: 2342,
		text: `<p>While you are fishing, you see a merman's head break the surface. "What are you doing?" he asks. He finds it hard to believe you can catch fish from above the surface of the water. He bids you to follow him, promising you a huge catch. Although you have to surface every minute or so, following his techniques you catch so many fish, you end up selling most of them to the market. [D1/W+1 (Max: Poor)]</p>`,
	},
	2343: {
		index: 2343,
		text: `<p>The other emanates such power—and such malice—that you make sure your paths do not cross. [D1]</p>`,
	},
	2344: {
		index: 2344,
		text: `<p>The other approaches you. "I am looking for subjects for my studies. Are you interested?"</p>
<p><b>No Skill:</b> You feign muteness, shake your head "no," and continue on your journey. [D1]</p>
<p><b>Magic:</b> At first you refuse, but then curiosity and the thirst for knowledge gets the better of you. You agree to help the other and in return, you are taught many things. [S1/Magic]</p>`,
	},
	2345: {
		index: 2345,
		text: `<p>The other glares at you as you try very hard not to meet her gaze. Soon, she has passed and you discover you have been holding your breath in fear. [S1]</p>`,
	},
	2346: {
		index: 2346,
		text: `<p>You espy a merman, unprovoked, attack an innocent victim then flee into the water. You follow the merman back to his surface lair and make note of the location so that you can direct the city guards here without fail. [D1/Quick Thinking]</p>`,
	},
	2347: {
		index: 2347,
		text: `<p>A merman walks the quay of this town, apparently a familiar sight here. One second he is standing quietly among some merchants and the next, fickle as the tides of the sea, he is raining blows in all directions. When he is done, he calmly walks away.</p>
<p><b>No Skill:</b> You were not confident enough to confront the merman during his state of rage, but you follow him to see where he flees. Unfortunately, he dives into a nearby body of water and disappears. [S1]</p>
<p><b>Weapon Use:</b> Drawing your sword, you attack. The merman runs and you chase after him, cornering him at the docks. Unfortunately, you forgot the nature of the one you follow and he dives into the water, lost to your sight. [D1]</p>
<p><b>Dendan Oil:</b> The merman dives into a nearby body of water. Quickly, you apply the Dendan Oil to your body and dive in after him. You surprise him and are able to bring him back to the surface into the arms of waiting guards. The merchants thank you and reward you for your efforts. [D1/W+2 (Max: Rich)/Lose <b>Dendan Oil</b>]</p>`,
	},
	2348: {
		index: 2348,
		text: `<p>You witness an infidel dweller of the oceans administering a harsh beating to a beggar. You are too afraid to help, but after the deed is done, you follow the culprit to its lair and note the location, and then bring an armed mob to seize and punish the merman for all his foul deeds. [D1]</p>`,
	},
	2349: {
		index: 2349,
		text: `<p>You carefully avoid being drawn in by the dazzling looks and sad eyes of the other. They are obviously in a story of which you want no part. [S-1]</p>`,
	},
	2350: {
		index: 2350,
		text: `<p>It's very hard not to react to the attentions of the other, but you steel yourself and walk away. [S1]</p>`,
	},
	2351: {
		index: 2351,
		text: `<p>Although you are showered with gifts and attention, you don't want to be a part of the other's world.</p>
<p><b>No Skill:</b> Your graceless refusal of their attentions insults the other greatly. The other summons guards to teach you a lesson. [S1/<em>Wounded</em>]</p>
<p><b>Courtly Graces:</b> In words that would satisfy even a sultan, you convey to the other your desire to be left alone. So charmed, the other agrees—if you would but accept a single gift from them. [S1/<b>Treasure</b>]</p>
<p><b>Appearance</b> [if the opposite sex from the other]: No matter how hard you try to convince the other you wish no part of them, they cling to you, devote themselves to you. At some point you are able to escape from their presence but you know you will see them again. [<em>Beloved</em>]</p>`,
	},
	2352: {
		index: 2352,
		text: `<p>While walking through the busy marketplace, you are approached by a veiled woman. She gives you a purse of gold and begs you to buy her at the slave market. Sure enough, when you arrive there, she is up for auction—and the bidding escalates quickly. You look into the purse—there are easily a hundred gold coins here, a fortune for a slave! You easily outbid everyone, including a scowling man in rich robes. The slave says quietly, "Thank you for saving me from that monster. He had me sold as a slave only to buy me to make it legal. My father will reward you handsomely—but you must watch your back as you have acquired a powerful enemy." [S1/W+3 (Max: Princely)/<em>Pursued</em> (MERCHANT)]</p>`,
	},
	2353: {
		index: 2353,
		text: `<p>The slave market is busy, buzzing with sounds of selling and buying. Then, a new slave, hooded, appears, ready to be auctioned. Everything goes silent—no noise whatsoever is heard. You look around at all the entranced faces, then catch the eyes of the slave. A will not your own compels you to shout "One gold coin!" "Sold!"—and with that sound returns to the marketplace. Suddenly the slave appears besides you, revealing himself to be a wizard. Luckily, he perceived you as having a kind soul and had enough power left to him to choose you over the others to buy him. He returns your gold coin—and a small purse full of more like it—as a reward, then bids you farewell. [S2/W+2 (Max: Rich)]</p>`,
	},
	2354: {
		index: 2354,
		text: `<p>You are in the market for a slave to help you in your travels. However, the choices available are few and expensive. You turn to leave and standing in front of you is a toothless, pock-marked man, holding the arm of a veiled woman. "I have what you need and it will not cost you much."</p>
<p><b>No Skill:</b> You give some gold to them and lead your acquisition away. You don't get too far when you are confronted by the guards, accusing you of abduction. You say you bought the slave legitimately, but one of the guards was at the auction and doesn't recall this slave being auctioned. The veiled woman affirms this by revealing herself to be an old hag—none would ever buy her as a slave. You are arrested, a victim of a con. [W-1 (Min: Penniless)/<em>Imprisoned</em>]</p>
<p><b>Wisdom, Scholarship:</b> While slave masters are not known to be good and decent people, you do know that there are rules for selling slaves, and approaching a buyer like this is against standards and practices. You hold onto your money and depart in haste. [Choice of Wisdom or Scholarship]</p>`,
	},
	2355: {
		index: 2355,
		text: `<p>The other offers you a "position" in his work for a handsome fee. Afterwards, because of what you have witnessed and done, you are haunted by black thoughts and dizziness. [W+1 (Max: Respectable)/Lose one skill of your choice]</p>`,
	},
	2356: {
		index: 2356,
		text: `<p>You almost regret accepting the offer to help the other, but afterwards, you feel better than you have in years. [W+1 (Max: Respectable)/Gain one skill of your choice that you do not possess]</p>`,
	},
	2357: {
		index: 2357,
		text: `<p>The other says, "I have need of freshly deceased bodies to continue my work. I shall pay you fifty pieces of gold for each body you bring me."</p>
<p><b>No Skill:</b> You don't mind helping especially since coin is involved, but soon the grisly work catches up to you. You offer humble apologies and ask to depart. [W+1 (Max: Respectable)]</p>
<p><b>Piety:</b> The idea of desecrating deceased bodies is appalling to your faith. However, under the pretense of agreeing to help the other, you get word to the sultan about the other's activities and an ambush is set up whereby the other is arrested. The sultan rewards you generously. [S1/W+4 (Max: Princely)]</p>`,
	},
	2358: {
		index: 2358,
		text: `<p>You stumble upon the other about to cast a spell on a young maiden. Without further thought, you unsheathe your blade and charge forward.</p>
<p><b>No Skill:</b> Your strike fells the other. Instead of gratitude, the maiden, showers you with blows and curses. "It has taken me years to find someone who could lift the enchantment I'm under! Now I must suffer even longer." Her words sadden you—perhaps next time you will be less rash with your actions. [S1/<em>Grief Stricken</em>/<em>Accursed</em>]</p>
<p><b>Magic:</b> You are unsure what the other plans to do so you react quickly by displaying your power, casting the other to the floor. The maiden turns to you. "Idiot! I was finally going to be rid of the curse I'm under but you have ruined my chance. I curse you in the name of Allah!" With those words you feel your body warp and melt. [<em>Beast Form</em>]</p>`,
	},
	2359: {
		index: 2359,
		text: `<p>The other divines your intention but remains steadfast. "Do what you feel you must do." At these words you are shamed and ask for forgiveness. [Piety]</p>`,
	},
	2360: {
		index: 2360,
		text: `<p>You have been treated poorly in the past by those who practice the Arts, and though the other has a good reputation, you nevertheless find yourself driven to violence.</p>
<p><b>No Skill:</b> Your blows reduce the other to a bloody mess. You stare at your weapon with awe—truly, steel is mightier than magic! But when you look back toward your victim, there is nothing there save a small scrap of parchment. When you pick it up, immediately it disappears in a flash. You shrug, and continue on your way, stumbling every few steps, though you know not why. [<em>Accursed</em>]</p>
<p><b>Piety:</b> Before you do something regrettable, your faith calms your breast. It matters not what methods are used to spread kindness and gentility to others, but those that do so should be honored, not hated. You bring yourself to smile in appreciation of the other's deeds before you head on your way. [D1/Wisdom]</p>`,
	},
	2361: {
		index: 2361,
		text: `<p>Your offer of aid brings a laugh of contempt from the other, and you are turned into a donkey. "That is the only way you could be of use to me!" [<em>Beast Form</em>]</p>`,
	},
	2362: {
		index: 2362,
		text: `<p>You offer the other your respectful greetings, and ask whether you may be of any assistance. The other looks you up and down and says, "Indeed, I could use your help. There is one who owes me a large sum of money. I would like you to retrieve it for me."</p>
<p><b>No Skill:</b> You follow the directions on finding this person and when you do, you accost them roughly, demanding money. "You dare soil my robes with your beggar hands? Guards, arrest this vagrant!" The other took you for a fool and rightly so: next time, you will get more detail about someone you are supposed to approach so that you don't run blindly into another Vizier. [D1/Wisdom/<em>Imprisoned</em>]</p>
<p><b>Scholarship, Wisdom:</b> You immediately recognize the "debtor" as the Vizier of this land, and realize the other has tried to make a fool of you. You turn the tables by telling the Vizier that the other is spreading false and vicious rumors about him. The Vizier has the other arrested and you are rewarded for your loyalty. [D2/W+1 (Max: Respectable)/<b>Robe of Honor</b>]</p>`,
	},
	2363: {
		index: 2363,
		text: `<p>You offer your services to the other, who offers a nice purse as payment. After performing your service you are given only the purse. "I did say your payment would be a nice purse. And I happen to think that is a very nice purse." You leave, prepared for the next time you have to deal with those who wield the Dark Arts. [Wisdom]</p>`,
	},
	2364: {
		index: 2364,
		text: `<p>You have something of interest to the other, who wishes to purchase it from you.</p>
<p><b>No Skill:</b> You accept the payment of one gold coin. The other puts it in your hand, but before you can close your fist, the coin is gone! You call the other back to explain the situation. With raised eyebrow, the other warily puts another coin in your hand. You make a fist but when you open it again, you discover the coin is gone! Frustrated, you turn, but the other laughs and says, "You have been a good sport. Come, let me pay you for the entertainment you have provided me. And in your hand is a purse of gold is placed. [W+1 (Max: Respectable)]</p>
<p><b>Bargaining and Evaluation:</b> You haggle for a higher price, but the other becomes angry. "Come now, you are wasting my time. Let us trade or let us part." You declare a fair price but then the other balks. "First you thought your item was worth much more and now you have come down so far in value, I cannot believe this item is worth anything." And with that he departs, leaving you in a confused state. [S1]</p>`,
	},
	2365: {
		index: 2365,
		text: `<p>Realizing the nature of the one you have met, you spin a fantastical yarn of deceptions and trickery, of the pompous humiliated and the quick-witted triumphant. The other laughs and rewards you for the entertainment. [Storytelling]</p>`,
	},
	2366: {
		index: 2366,
		text: `<p>Drawing your weapon, you leap at the other with a proud battle cry.</p>
<p><b>No Skill:</b> The other raises a hand, and your weapon wrenches itself from your hand. Another gesture, and it attacks you as though it were wielded by an invisible djinn. [<em>Wounded</em>]</p>
<p><b>Weapon Use:</b> The other gestures and your sword transforms into a snake! Without hesitation, you strike the other with the reptile and it bites the other. Instead of a quick death, the other lies writhing on the floor, slowly dying, as the serpent's poison courses through their body. [D1/Quick Thinking]</p>`,
	},
	2367: {
		index: 2367,
		text: `<p>The other laughs at your impertinence and with an offhanded gesture, transforms your sword into a snake! You fling it from you in horror, and take to your heels. [D-1]</p>`,
	},
	2368: {
		index: 2368,
		text: `<p>Your weapon moves like the lightning from a spring storm, and the other is taken by surprise.</p>
<p><b>No Skill:</b> Your blade encounters nothing but empty air; the other has disappeared like morning mist, leaving only the echoes of their laughter. [S1]</p>
<p><b>Wisdom:</b> At the last moment, you think better of attacking a wielder of magic with weapons of mere steel. So you decide to put on a show of skill by fighting an invisible foe to the delight of the other. In praise of your skill, you are given a small gift. [Weapon Use/<b>Magic Bead</b>]</p>`,
	},
	2369: {
		index: 2369,
		text: `<p>The other laughs with delight at the thought that one such as you would dare to trick one such as they. "Take my blessing as a reward for amusing me," the others says before turning away, still chuckling. [<em>Blessed</em>]</p>`,
	},
	2370: {
		index: 2370,
		text: `<p>You launch into a prepared speech, thinking yourself more clever than a tree full of monkeys.</p>
<p><b>No Skill:</b> But suddenly your voice is muffled—for your mouth has disappeared like a healed wound. "Be careful," says the other, "of whom you would seek to deceive." Your mouth returns, but you keep it closed, and leave. [Wisdom]</p>
<p><b>Appearance:</b> Your story and your handsome face cannot fail to succeed, you think—but suddenly you find that you stink, and your whole body is covered with boils. "Do not presume to trick a trickster," says the other with a laugh. [D1/Lose Appearance]</p>`,
	},
	2371: {
		index: 2371,
		text: `<p>You give a performance that would convince a Sultan.</p>
<p><b>No Skill:</b> But suddenly you realize the tables have been turned upon you. Instead of tricking the other into believing your virtue, you are boasting of the most heinous crimes before a crowd of onlookers. You escape before you can be arrested, but you are a wanted, self-confessed criminal. [<em>Outlaw</em>]</p>
<p><b>Beguiling:</b> The other listens to your tale gravely, but at the end turns an indulgent smile upon you, as a parent smiles upon a precocious child. "That was well told, but you still have much to learn." You spend some time with the other learning to craft tales more convincingly by magical means. [Magic]</p>`,
	},
	2372: {
		index: 2372,
		text: `<p>You hire the other in order to intimidate one that who oppressed you in the past.</p>
<p><b>No Skill:</b> As you conclude the deal, the other turns you into a giant, black djinn that you might confront your tormentor. Unfortunately, your voice does not match your stature and the words you speak instill laughter instead of fear. Perhaps you will learn to manipulate your voice to augment your disguise. [D1/Acting and Disguise/<em>Scorned</em>]</p>
<p><b>Bargaining and Evaluation:</b> As you congratulate yourself on getting the services of the other for a mere pittance, you soon regret your decision as the other displays no skills whatsoever, and he makes a fool of you in front of your oppressor. As you turn to confront the other, you see his double at a merchant's stall! You stride over to the stall and demand to know what is going on. "You didn't expect to hire me personally for the amount you offered, did you? I put a glamour on my slave to portray me in my stead." You are made an even bigger fool and to a larger audience. [S1/<em>Scorned</em>]</p>`,
	},
	2373: {
		index: 2373,
		text: `<p>Approaching the other warily, you inquire whether their services might be available for hire.</p>
<p><b>No Skill:</b> "Not for the likes of you!" Before you can make any answer, the other disappears, leaving only their laughter echoing behind. [D1]</p>
<p><b>Piety:</b> "Your faith will serve you better than I can," they reply, taking you by surprise. "I had thought to play some harmful trick on you, but I see that you deserve better." You part ways, no better off but no worse. [D2]</p>`,
	},
	2374: {
		index: 2374,
		text: `<p>You see the other make a fool of a merchant and think twice about asking them to join you. [S1]</p>`,
	},
	2375: {
		index: 2375,
		text: `<p>The other's voice booms in your ear. "What is your life worth?" Caught off-guard, you know not what to say: you never expected to be bargaining for your life this day.</p>
<p><b>No Skill:</b> You start babbling, then pleading for your life to be spared.</p>
<p><em>If your Wealth is Respectable or greater:</em> You offer gold, jewels, slaves—but nothing interests the other. Soon, he shakes his head. "You are completely beneath my consideration." So saying this, the other vanishes in a dark cloud of smoke. [D-1]</p>
<p><em>If your Wealth is Poor or less:</em> Saddened, you say you have nothing to offer. The other shakes his head. "You have more to offer than material goods. Allah created men for a higher purpose in life than to just wallow in material things. Your potential is greater than all the wealth in a Sultan's treasury." The other departs in a cloud of smoke, leaving you to ponder his words carefully. [D1/Wisdom]</p>
<p><b>Piety:</b> "My life," you begin, "has the same value as all of Allah's creatures." The other, surprised at the strength of your faith, bows low and departs. [D2]</p>`,
	},
	2376: {
		index: 2376,
		text: `<p>The other casts a baleful eye towards you and freezes you in place. Fearing these may be your last moments, you plead for a respite to take care of important family business. You promise to return after visiting your home. The other's face looks perplexed. "The one I seek has no family. You may go on your way with my apologies." With that the other departs, leaving you holding a wondrous object. [Luck/<b>Treasure</b>]</p>`,
	},
	2377: {
		index: 2377,
		text: `<p>You approach on bended knee, showing the utmost respect to the other. You plead for an audience, requesting to use their talents for some small gain. The other responds with complete revulsion, "I have no desire to delve further into your miserable life. I leave you to your own devices." [S1]</p>`,
	},
	2378: {
		index: 2378,
		text: `<p>A friend of yours cites a tale of treachery and thievery: while he was pearl diving, a merman attacked him and stole the pearls he had gathered. You immediately draw your sword and vow to find this merman and take back what was stolen.</p>
<p><b>No Skill:</b> You search the shore for a long time but the merman never appears. [S1]</p>
<p><b>Enduring Hardship:</b> You perch atop some rocks, staring out into the water for hours, and are finally rewarded with the appearance of the merman. The merman leaves a sack on the sand and then dives back into the water. You seize the sack and retreat to your perch. Within are more pearls, gems and jewels than ever your friend could have gathered—taking this sack will be payment in full for the merman's crime. [S1/W+2 (Max: Rich)]</p>`,
	},
	2379: {
		index: 2379,
		text: `<p>By providence, you stumble upon the lair of a merman bandit who has been causing much trouble in this area, far from the sea. He is asleep and it would be a simple matter to steal his ill-gained goods, and then perhaps bring round the guards here to collect a bounty.</p>
<p><b>No Skill:</b> You decide that you have done enough to help and head on your way. Your venture is modestly profitable. [S1/W+2 (Max: Respectable)]</p>
<p><b>Piety:</b> However, the still, clear voice of your faith stops you. Instead of robbing him, you awaken him and question him about his actions. Soon you learn that it is the land people who have victimized him! All that you see in his cave are his own goods, stolen back from the people who took advantage of a stranger. You ask to escort him back to the sea, many miles away. When you arrive at a distant harbor city, he sheds his disguise and underneath you see he is dressed in princely robes! "You had every opportunity to turn on me," he says with a smile, "But you chose not to. There is a place in my court for one such as you." [D2/W+3 (Max: Princely)/<em>Vizier</em>]</p>`,
	},
	2380: {
		index: 2380,
		text: `<p>A string of robberies have been plaguing the area, and luckily, you spot the culprit—a merman!—depositing his ill-gotten goods in a nearby lake. Patiently, you sit watching until he re-emerges from the water and heads off. Then you dive in, carrying as much as you can from his makeshift home.</p>
<p><b>No Skill:</b> You return some of the treasure to the victims, but keep the bulk of it for yourself. [W+2 (Max: Respectable)/<em>Determined</em>]</p>
<p><b>Dendan Oil:</b> You return all the treasure to their respective owners, and are even left with something for yourself. The people applaud your actions. [D1/W+2 (Max: Rich)/<em>Respected</em>]</p>`,
	},
	2381: {
		index: 2381,
		text: `<p>The other's deplorable attitude ignites your anger and you draw your sword. The eyes of the other widen as he sputters out apologies and a promise to change for the better. [S1]</p>`,
	},
	2382: {
		index: 2382,
		text: `<p>The other approaches, begging for alms. You hit the scoundrel for his impertinence, but his friends see this and beat you. [S1/<em>Wounded</em>]</p>`,
	},
	2383: {
		index: 2383,
		text: `<p>The other, hearing of your exploits, wishes to join you on your adventures. He follows you everywhere, disrupting your business, and finally have had enough.</p>
<p><b>No Skill:</b> You cuff him across the face, sending him sprawling to the ground. Those around jeer your violence towards this wretch. [S1/<em>Scorned</em>]</p>
<p><b>Weapon Use:</b> You deftly cut his robes with your scimitar. "When you learn to master a sword like this, then you may join me!" The other bows graciously, happy for a purpose in life. [D1]</p>`,
	},
	2384: {
		index: 2384,
		text: `<p>The unkempt dress of the other as he approaches makes you wary enough to draw your sword. The other asks a small boon of you but you answer with the flat of your blade. "Is this how you treat a fellow Muslim? May Allah rain down upon you a thousand curses!" The power in the other's voice has you looking up in anticipation of this rain—and while nothing strikes you at the moment, the next few days see you plagued with ill luck. [D1/<em>Accursed</em>]</p>`,
	},
	2385: {
		index: 2385,
		text: `<p>The other comes to you as one in need and says that one of your skills can certainly be of great assistance. You are eager to help on in distress. With haste the other leads you out of town ... to a burial-ground. "Grab up a shovel—I need three fresh bodies for my experiments!"</p>
<p><b>No Skill:</b> You cry out in revulsion at the monstrosity you have been asked to perform. The other looks surprised and, with a sad shake of the head, says, "I thought I had found a true partner in my great work. Be gone with you." With that, you are ... somewhere else. [S1/Have another player move you to any space except a Place of Power]</p>
<p><b>Quick Thinking:</b> You stifle a cry of revulsion and pick up a shovel as you were told. When the other turns away from you, you strike them with every scrap of force you can summon, and split their head like a melon. Thus always to those who would blaspheme the dead! [D1/Piety]</p>`,
	},
	2386: {
		index: 2386,
		text: `<p>"When you have pierced the veil of the natural world as I have, such mundane appetites as you have hold no meaning for me. Begone!" [S1]</p>`,
	},
	2387: {
		index: 2387,
		text: `<p>"You must have a life outside these books and scrolls," you tell the other. "Everything I need in life is in these books!" is the response you get.</p>
<p><b>No Skill:</b> There is no reason to pursue your desire further. [D1]</p>
<p><b>Wisdom:</b> You reply, "Can you eat these books?" The other looks up and smiles. "Some functions these books cannot provide. Let us away for a while then." And "a while" turns out to be a joyous night and a day. [D1/Seduction]</p>`,
	},
	2388: {
		index: 2388,
		text: `<p>The other is too absorbed in his studies to listen to you.</p>
<p><b>No Skill:</b> You cannot dissuade the other to spend time on you. [S1]</p>
<p><b>Any Treasure:</b> On a hunch, you pull out from your robes a wondrous artifact which ignites the curiosity of the other. "I must study this item," the other says. You promise to let him have it if only he will spend some time with you on frivolous, but human matters. [D1/S1/Seduction/Lose one <b>Treasure</b> of your choice]</p>`,
	},
	2389: {
		index: 2389,
		text: `<p>You resolve to fool the other into assisting you, but you immediately sense nothing behind their eyes. Nothing you will say or do could produce anything of value to you. [S-1]</p>`,
	},
	2390: {
		index: 2390,
		text: `<p>You are told that your victim has lost their wits but not their wealth. So you don the skin of an animal and beg for aid in regaining human form. The other takes you into their workshop, where you take note of valuable objects.</p>
<p><b>No Skill:</b> The other talks about the procedures involved in turning you back to normal and has you undergo excruciating trials, made to drink the foulest-tasting liquids, and to do rather inappropriate things with strange tools. Finally, the other laughs, loud and long. "I have never been so entertained as I have been this day. I'm sorry to have made you the scapegoat, but you should not believe everything you are told." You have learned a valuable lesson. [D1/Wisdom]</p>
<p><b>Acting and Disguise:</b> Your actions so perfectly mimic the animal you are pretending to be that the other is quite eager to help you return to normal. When they are done with their work, you leave with more than you came in. [D1/Stealth and Stealing/<b>Treasure</b>]</p>`,
	},
	2391: {
		index: 2391,
		text: `<p>You try to fool the other into granting you a favor, feeling that he would not be likely to grant your request directly. You spin a complex lie which tells of the great benefit that will come to him if he aids you.</p>
<p><b>No Skill:</b> Your lie is transparent, and he is not fooled for an instant. Instead, he punishes you severely for your duplicity. [D-1/<em>Wounded</em>]</p>
<p><b>Storytelling, Protective Talisman</b> [mandatory]: You immediately sense that your lie is not convincing the other, and you change tactics; your lie becomes a parable of the rewards that await those who aid others. The other is moved by your words, and when you request his aid directly, it is granted. [D1/S1/Piety]</p>`,
	},
	2392: {
		index: 2392,
		text: `<p>The other is quite fetching and agrees to your kind offer of help. The other, it seems, is plagued by a former lover, and though the other could easily turn the other into a frog, out of the love they once shared he would rather dissuade her attentions more gently.</p>
<p><b>No Skill:</b> You seek out the former lover and convince her that if she continues to importune the other, she will find herself living in a pond. The lover clearly receives the message, and the other gives you a small gift for your troubles. [S1/W+2 (Max: Rich)]</p>
<p><b>Acting and Disguise:</b> You show the other how to make himself appear to be suffering from a horrible, disfiguring disease. The other then goes to his former love, who flees in disgust, never to return. For your trouble, the other gives you a token of his esteem. [D1/<b>Treasure</b>]</p>`,
	},
	2393: {
		index: 2393,
		text: `<p>Though the other is great in the ways of magic, he readily admits to being a novice in the arts of love. He has deeply offended his beloved, and wishes your assistance in re-winning her heart. You know just the trick—flowers and a full moon, which will show the other to the greatest romantic advantage.</p>
<p><b>No Skill:</b> You rush into town and appeal to sympathies of a dozen florists, putting together a bouquet of such beauty that even a statue's heart would melt. The other thanks you and rushes off to the late-night rendezvous. The next morning he informs you that he is now betrothed to the King's daughter, and he showers you with rewards. [S1/W+2 (Max: Rich)/Seduction]</p>
<p><b>Stealth and Stealing:</b> You move quietly through the marketplace, gathering flowers while no-one notices.. You bring them to the other, who thanks you and runs off quickly. You can only hope the situation works out for him. [S1]</p>`,
	},
	2394: {
		index: 2394,
		text: `<p>You agree to assist a magician in a complex ritual to be performed at night beneath the open sky outside the town. When you arrive, there are several other assistants, including a drummer. The other arrives and instructs you all in the parts you will play. When the drumming begins, the other throws aside his robes and stands nude before the sky! The drummer is so distracted by the sight that he falls silent.</p>
<p><b>No Skill:</b> You grab up the drum, but you cannot keep the complex beat of the other's chant. The spell fails and the other leaves in fury. [S1]</p>
<p><b>Courtly Graces, Acting and Disguise:</b> You easily pick up the beat, and the ritual is completed with no further interruptions. When it is done, the other rewards you handsomely. [D1/S1/<b>Treasure</b>]</p>`,
	},
	2395: {
		index: 2395,
		text: `<p>The bearing of the other bespeaks a higher station. "My father, the King of the People of the Smokeless Flame, is about to go to war with the Sultan of this land. With your kind demeanor, you could argue the case for your people and stop the impending bloodshed. Will you help?"</p>
<p><b>No Skill:</b> Even the thought of approaching such a great and terrible figure is more than you are able to handle. You shake your head sadly and walk away. [D-1]</p>
<p><b>Courtly Graces:</b> With your experience in the worlds of palace intrigue, you hit upon a stratagem that you are sure will work. You gain an audience with the Sultan and through wise words you are able to create a treaty that benefits both parties. You are hailed as a hero. [D2/S1/<b>Robe of Honor</b>/<b>Treasure</b>]</p>`,
	},
	2396: {
		index: 2396,
		text: `<p>You round a corner in the road you walk and see before you a cave, blocked by great stones. Sitting on the largest of the stones is one draped in fine clothing that bespeaks great wealth. "My brother, a prince among my kind, is trapped in that cave. Only a mortal can open it. I miss him so much—can you help?" The sadness in the other's voice convinces you to assist.</p>
<p><b>No Skill:</b> So you aid in removing the rock from the cave's entrance. No sooner than the deed is done do the prince and his conniving sibling push you into the cave and seal it up! You have learned a valuable lesson in trust. [You do not move next turn but you will draw an encounter card]</p>
<p><b>Scholarship, Wisdom:</b> However, as you come closer, you notice words of power carved into the rock: this is not a normal imprisonment and the prisoner must be very powerful indeed. You feign a strained back and start hobbling away. The other hastens your retreat with a bolt of lightning, but cannot pursue you past the rock that is a prison to them both. [D1/S2]</p>`,
	},
	2397: {
		index: 2397,
		text: `<p>You espy a bottle on the ground. As you approach, a voice booms out: "Free me from this bottle and I'll grant your every desire, for I am a prince among my people and my power is infinite."</p>
<p><b>No Skill:</b> You retort, "If your power were truly infinite, you would not need my help!" And thus saying, you continue on your journey. [D1/S1]</p>
<p><b>Envious</b> [mandatory]: Thinking that all you desire might finally be granted to you, you hasten to perform this simple task. As you open the bottle, smoke issues forth. Laughter booms from within the cloud. "Foolish mortals, will you never understand the price for helping one of the mighty 'efreet?" The smoke covers your head and you pass out. When you awaken, you are not where you were. [S1/Have another player move you three spaces in any direction]</p>`,
	},
	2398: {
		index: 2398,
		text: `<p>You smile at the sight before you, the other trapped in a strange device. Although they plead for your help, claiming their entrapment was by their own hands, you feel it is better to leave well enough alone—though it will make for an amusing tale during your travels. [S1]</p>`,
	},
	2399: {
		index: 2399,
		text: `<p>The other seems to have trapped himself in a cocoon of sparkling lights. You beat a hasty retreat lest you become a victim of their ineptness. [D-1]</p>`,
	},
};
